#Requires -Version 5.1
<#
.SYNOPSIS
    CIS Microsoft Windows 11 Enterprise Benchmark v5.1.0 L1 - Standalone Auditor

.DESCRIPTION
    Fully self-contained, single-file PowerShell compliance audit script.
    - Zero external dependencies: NO Python, NO pip packages, NO Microsoft Office/Excel required.
    - Embedded Benchmark: The complete CIS Windows 11 Enterprise v5.1.0 L1 audit definitions are embedded.
    - Dual Reporting: Generates companion CSV and native styled OpenXML Excel (.xlsx) reports.
    - Designed specifically for SCCM / MECM, Intune, Group Policy, and automated endpoint execution.

.PARAMETER AuditFile
    Optional path to an external Nessus .audit file. If omitted, the embedded CIS v5.1.0 L1 benchmark is used.

.PARAMETER OutputDir
    Directory path where reports should be written. Defaults to the script's directory.

.PARAMETER OpenReport
    Switch to automatically launch the generated Excel/CSV report upon audit completion.

.EXAMPLE
    # Run audit locally or via SCCM Run Script:
    powershell.exe -ExecutionPolicy Bypass -File "CIS_Windows11_Enterprise_Audit.ps1"

.EXAMPLE
    # Run and automatically open the Excel report:
    .\CIS_Windows11_Enterprise_Audit.ps1 -OpenReport
#>
[CmdletBinding()]
param (
    [Parameter(Mandatory = $false, Position = 0)]
    [string]$AuditFile = "",

    [Parameter(Mandatory = $false)]
    [string]$OutputDir = "",

    [Parameter(Mandatory = $false)]
    [switch]$OpenReport = $false
)

# 1. Execution Policy configuration
Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force -ErrorAction SilentlyContinue

# 2. Check for Administrator Privileges
$IsAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
    [Security.Principal.WindowsBuiltInRole]::Administrator
)

$ScriptDir = if ($PSScriptRoot) { $PSScriptRoot } else { Split-Path -Parent $MyInvocation.MyCommand.Definition }
if (-not $ScriptDir) { $ScriptDir = (Get-Location).Path }

$ReportDir = if ($OutputDir -and (Test-Path -LiteralPath $OutputDir -PathType Container)) {
    (Resolve-Path $OutputDir).Path
} else {
    $ScriptDir
}

try { $Host.UI.RawUI.WindowTitle = "CIS Windows 11 Enterprise - Compliance Auditor" } catch {}

Write-Host "===============================================================================" -ForegroundColor Cyan
Write-Host "         WINDOWS 11 ENTERPRISE CIS BENCHMARK CONFIGURATION AUDITOR             " -ForegroundColor Cyan
Write-Host "         Benchmark: CIS Microsoft Windows 11 Enterprise v5.1.0 L1               " -ForegroundColor Cyan
Write-Host "===============================================================================" -ForegroundColor Cyan

if ($IsAdmin) {
    Write-Host "[+] Elevated Privileges : DETECTED (Administrator Mode - Full Inspection)" -ForegroundColor Green
} else {
    Write-Host "[!] Elevated Privileges : NOT DETECTED (Standard User - Partial Mode)" -ForegroundColor Yellow
    Write-Host "    Tip: To perform complete inspection of User Rights and Secedit policies," -ForegroundColor DarkYellow
    Write-Host "    execute this script as Administrator or via SCCM LocalSystem." -ForegroundColor DarkYellow
}

