function Load-AuditContent {
    param([string]$SpecifiedPath, [string]$BaseDir)

    # 1. Specified file path
    if ($SpecifiedPath -and (Test-Path -LiteralPath $SpecifiedPath)) {
        Write-Host "[+] Loading user-specified audit file: $SpecifiedPath" -ForegroundColor Green
        return (Get-Content -Raw -LiteralPath $SpecifiedPath -Encoding UTF8)
    }

    # 2. Local folder candidates
    $candidates = @(
        (Join-Path $BaseDir "CIS_Microsoft_Windows_11_Enterprise_v5.1.0_L1.audit"),
        (Join-Path $BaseDir "audit\CIS_Microsoft_Windows_11_Enterprise_v5.1.0_L1.audit"),
        (Join-Path (Get-Location) "CIS_Microsoft_Windows_11_Enterprise_v5.1.0_L1.audit")
    )
    foreach ($c in $candidates) {
        if (Test-Path -LiteralPath $c) {
            Write-Host "[+] Located audit file on disk: $c" -ForegroundColor Green
            return (Get-Content -Raw -LiteralPath $c -Encoding UTF8)
        }
    }

    # 3. Decompress embedded benchmark
    Write-Host "[*] Extracting embedded CIS benchmark definitions..." -ForegroundColor Cyan
    $bytes = [System.Convert]::FromBase64String($EmbeddedAuditGzBase64)
    $ms = New-Object System.IO.MemoryStream(,$bytes)
    $gz = New-Object System.IO.Compression.GZipStream($ms, [System.IO.Compression.CompressionMode]::Decompress)
    $sr = New-Object System.IO.StreamReader($gz, [System.Text.Encoding]::UTF8)
    $content = $sr.ReadToEnd()
    $sr.Close(); $gz.Close(); $ms.Close()
    Write-Host "[+] Embedded benchmark extracted successfully ($([Math]::Round($content.Length / 1KB, 1)) KB)." -ForegroundColor Green
    return $content
}

