# ==============================================================================
# SECTION 3: AUDIT BENCHMARK PARSER
# ==============================================================================
function Extract-Field {
    param([string]$Block, [string]$FieldName)
    $pattern = "(?m)^\s*$([regex]::Escape($FieldName))\s*:\s*(.*?)(?=^\s*[A-Za-z_][A-Za-z0-9_]*\s*:|\Z)"
    $m = [regex]::Match($Block, $pattern, [System.Text.RegularExpressions.RegexOptions]::Singleline -bor [System.Text.RegularExpressions.RegexOptions]::Multiline)
    if (-not $m.Success) { return "" }
    $val = $m.Groups[1].Value.Trim()
    if ($val.Length -ge 2 -and $val[0] -eq $val[-1] -and ($val[0] -eq '"' -or $val[0] -eq "'")) {
        $val = $val.Substring(1, $val.Length - 2)
    }
    return $val.Trim()
}

function Get-SpecificRuleId {
    param([string]$Description)
    if (-not $Description) { return "" }
    $m = [regex]::Match($Description.TrimStart(), '^[''"]?(\d+(?:\.\d+)+)(?![A-Za-z0-9_])')
    if ($m.Success) { return $m.Groups[1].Value }
    return ""
}

function Build-BenchmarkMap {
    param([string]$Text)

    $tagRe = [regex]'<(/?)if\b[^>]*>'
    $stack = New-Object System.Collections.Generic.Stack[int]
    $ifSpans = @()
    foreach ($tm in $tagRe.Matches($Text)) {
        if ($tm.Groups[1].Value -eq '/') {
            if ($stack.Count -gt 0) {
                $st = $stack.Pop()
                $ifSpans += [PSCustomObject]@{ Start = $st; End = $tm.Index + $tm.Length }
            }
        } else {
            $stack.Push($tm.Index)
        }
    }

    $reportRe = [regex]'(?si)<report\b[^>]*>(.*?)</report>'
    $reports = @()
    foreach ($rm in $reportRe.Matches($Text)) {
        $block = $rm.Groups[1].Value
        $desc  = Extract-Field -Block $block -FieldName "description"
        $rid   = Get-SpecificRuleId -Description $desc
        if ($rid) {
            $reports += [PSCustomObject]@{
                Start       = $rm.Index
                End         = $rm.Index + $rm.Length
                RuleId      = $rid
                Description = $desc
            }
        }
    }

    $mapping = @{}
    $itemRe  = [regex]'(?si)<custom_item>(.*?)</custom_item>'
    foreach ($im in $itemRe.Matches($Text)) {
        $iStart = $im.Index
        $iEnd   = $im.Index + $im.Length
        $raw    = $im.Groups[1].Value
        $iDesc  = Extract-Field -Block $raw -FieldName "description"
        $directId = Get-SpecificRuleId -Description $iDesc

        if ($directId) {
            $mapping["$iStart|$iEnd"] = [PSCustomObject]@{ RuleId = $directId; Description = $iDesc; Source = "custom_item" }
            continue
        }

        $containing = $ifSpans | Where-Object { $_.Start -le $iStart -and $iEnd -le $_.End }
        if (-not $containing) { continue }
        $innermost  = $containing | Sort-Object { $_.End - $_.Start } | Select-Object -First 1
        $ifStart    = $innermost.Start
        $ifEnd      = $innermost.End

        $candidates = @()
        foreach ($r in $reports) {
            if ($r.Start -lt $ifStart -or $r.End -gt $ifEnd) { continue }
            $repContaining = $ifSpans | Where-Object { $_.Start -le $r.Start -and $r.End -le $_.End }
            if (-not $repContaining) { continue }
            $innermostRepIf = $repContaining | Sort-Object { $_.End - $_.Start } | Select-Object -First 1
            if ($innermostRepIf.Start -eq $ifStart -and $innermostRepIf.End -eq $ifEnd) {
                $candidates += $r
            }
        }
        if (-not $candidates) { continue }

        $after = $candidates | Where-Object { $_.Start -ge $iEnd }
        if ($after) {
            $chosen = $after | Sort-Object { $_.Start - $iEnd } | Select-Object -First 1
        } else {
            $chosen = $candidates | Sort-Object { [Math]::Abs($_.Start - $iStart) } | Select-Object -First 1
        }

        $mapping["$iStart|$iEnd"] = [PSCustomObject]@{ RuleId = $chosen.RuleId; Description = $chosen.Description; Source = "if_report" }
    }
    return $mapping
}

function Parse-AuditFile {
    param([string]$Text)

    $variables = @{}
    $varBlocks = [regex]::Matches($Text, '(?si)<variable>(.*?)</variable>')
    foreach ($vb in $varBlocks) {
        $nm = [regex]::Match($vb.Groups[1].Value, '(?si)<name>(.*?)</name>')
        $df = [regex]::Match($vb.Groups[1].Value, '(?si)<default>(.*?)</default>')
        if ($nm.Success -and $df.Success) {
            $variables[$nm.Groups[1].Value.Trim()] = $df.Groups[1].Value.Trim()
        }
    }

    $benchMap = Build-BenchmarkMap -Text $Text

    $itemRe  = [regex]'(?si)<custom_item>(.*?)</custom_item>'
    $fieldRe = [regex]'(?m)^\s*([a-zA-Z_]+)\s*:\s*(.*?)$'
    $items   = @()

    foreach ($im in $itemRe.Matches($Text)) {
        $iStart = $im.Index
        $iEnd   = $im.Index + $im.Length
        $raw    = $im.Groups[1].Value

        $item       = @{}
        $fMatchList = [array]($fieldRe.Matches($raw))
        for ($fi = 0; $fi -lt $fMatchList.Count; $fi++) {
            $key      = $fMatchList[$fi].Groups[1].Value.Trim().ToLower()
            $colPos   = $raw.IndexOf(':', $fMatchList[$fi].Index)
            $valStart = $colPos + 1
            $valEnd   = if ($fi + 1 -lt $fMatchList.Count) { $fMatchList[$fi + 1].Index } else { $raw.Length }
            $val      = $raw.Substring($valStart, $valEnd - $valStart).Trim()
            if ($val.Length -ge 2 -and $val[0] -eq $val[-1] -and ($val[0] -eq '"' -or $val[0] -eq "'")) {
                $val = $val.Substring(1, $val.Length - 2)
            }
            foreach ($vname in $variables.Keys) {
                $val = $val -replace [regex]::Escape("@${vname}@"), $variables[$vname]
            }
            $item[$key] = $val
        }

        $mapKey = "$iStart|$iEnd"
        if ($benchMap.ContainsKey($mapKey)) {
            $item['benchmark_rule_id']     = $benchMap[$mapKey].RuleId
            $item['benchmark_description'] = $benchMap[$mapKey].Description
        } else {
            $item['benchmark_rule_id']     = ""
            $item['benchmark_description'] = ""
        }

        $items += $item
    }

    return $variables, $items
}

# ==============================================================================
# SECTION 4: ENVIRONMENT INSPECTION ENGINE
# ==============================================================================
$Script:SecpolData      = @{}
$Script:UserRightsData  = @{}
$Script:AuditpolData    = @{}
$Script:NetAccountsData = @{}
$Script:LocalUsers      = @{}

function Fetch-NetAccounts {
    try {
        $out = & net accounts 2>$null
        foreach ($line in $out) {
            if ($line -match ':') {
                $parts = $line -split ':', 2
                $Script:NetAccountsData[$parts[0].Trim().ToLower()] = $parts[1].Trim()
            }
        }
    } catch {}
}

function Fetch-LocalUsers {
    try {
        $ps = 'Get-CimInstance Win32_UserAccount -Filter "LocalAccount=True" | Select-Object Name,SID,Disabled | ConvertTo-Json -Compress'
        $out = powershell.exe -NoProfile -NonInteractive -Command $ps 2>$null
        if ($out) {
            $data = $out | ConvertFrom-Json
            if ($data -isnot [System.Array]) { $data = @($data) }
            foreach ($u in $data) {
                $Script:LocalUsers[$u.SID] = @{ Name = $u.Name; Disabled = $u.Disabled; SID = $u.SID }
            }
        }
    } catch {}
}

function Fetch-Secedit {
    $tmp = Join-Path $env:TEMP "cis_audit_secpol_$([System.Diagnostics.Process]::GetCurrentProcess().Id).cfg"
    try {
        & secedit /export /cfg $tmp /quiet 2>$null | Out-Null
        if (Test-Path -LiteralPath $tmp) {
            $section = ""
            $content = Get-Content -LiteralPath $tmp -Encoding Unicode -ErrorAction SilentlyContinue
            foreach ($line in $content) {
                $line = $line.Trim()
                if ($line -match '^\[(.+)\]$') { $section = $Matches[1].Trim(); continue }
                if ($line -match '=' -and $section) {
                    $kv = $line -split '=', 2
                    $k  = $kv[0].Trim()
                    $v  = $kv[1].Trim()
                    if ($section -eq 'System Access') {
                        $Script:SecpolData[$k.ToLower()] = $v
                    } elseif ($section -eq 'Privilege Rights') {
                        $Script:UserRightsData[$k] = $v
                    }
                }
            }
        }
    } catch {}
    try { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } catch {}
}

function Fetch-Auditpol {
    try {
        $out = & auditpol /get /category:* /r 2>$null
        if ($out) {
            foreach ($line in $out) {
                $cols = $line -split ','
                if ($cols.Count -ge 5 -and $cols[2].Trim() -and $cols[2].Trim() -ne 'Subcategory') {
                    $Script:AuditpolData[$cols[2].Trim().ToLower()] = $cols[4].Trim()
                }
            }
        }
    } catch {}
}

# ==============================================================================
# SECTION 5: REGISTRY INSPECTION (64-BIT & 32-BIT HIVES)
# ==============================================================================
function Read-Registry {
    param([string]$RegKey, [string]$RegItem)
    if (-not $RegKey -or -not $RegItem) { return $false, $null }

    $keyPath  = $RegKey.Replace('/', '\').Trim()
    $parts    = $keyPath -split '\\', 2
    $hiveName = $parts[0].ToUpper()
    $subkey   = if ($parts.Count -gt 1) { $parts[1] } else { "" }

    $hiveMap = @{
        "HKLM"                = [Microsoft.Win32.RegistryHive]::LocalMachine
        "HKEY_LOCAL_MACHINE"  = [Microsoft.Win32.RegistryHive]::LocalMachine
        "HKCU"                = [Microsoft.Win32.RegistryHive]::CurrentUser
        "HKEY_CURRENT_USER"   = [Microsoft.Win32.RegistryHive]::CurrentUser
        "HKU"                 = [Microsoft.Win32.RegistryHive]::Users
        "HKEY_USERS"          = [Microsoft.Win32.RegistryHive]::Users
        "HKCR"                = [Microsoft.Win32.RegistryHive]::ClassesRoot
        "HKEY_CLASSES_ROOT"   = [Microsoft.Win32.RegistryHive]::ClassesRoot
        "HKCC"                = [Microsoft.Win32.RegistryHive]::CurrentConfig
        "HKEY_CURRENT_CONFIG" = [Microsoft.Win32.RegistryHive]::CurrentConfig
    }

    if (-not $hiveMap.ContainsKey($hiveName)) { return $false, $null }
    $hiveEnum = $hiveMap[$hiveName]

    if ($hiveName -in @("HKU","HKEY_USERS") -and $subkey -notmatch '^S-1-5-') {
        $ok, $val = Read-RegDirect -HiveEnum ([Microsoft.Win32.RegistryHive]::CurrentUser) -Subkey $subkey -Item $RegItem
        if ($ok) { return $true, $val }
        try {
            $baseU = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::Users, [Microsoft.Win32.RegistryView]::Registry64)
            foreach ($sub in $baseU.GetSubKeyNames()) {
                if ($sub -match '^S-1-5-21-' -and $sub -notmatch '_Classes$') {
                    $fullSub = "$sub\$subkey"
                    $okU, $valU = Read-RegDirect -HiveEnum ([Microsoft.Win32.RegistryHive]::Users) -Subkey $fullSub -Item $RegItem
                    if ($okU) { $baseU.Close(); return $true, $valU }
                }
            }
            $baseU.Close()
        } catch {}
        return $false, $null
    }

    return Read-RegDirect -HiveEnum $hiveEnum -Subkey $subkey -Item $RegItem
}

function Read-RegDirect {
    param([Microsoft.Win32.RegistryHive]$HiveEnum, [string]$Subkey, [string]$Item)

    foreach ($view in @([Microsoft.Win32.RegistryView]::Registry64, [Microsoft.Win32.RegistryView]::Registry32)) {
        try {
            $baseKey = [Microsoft.Win32.RegistryKey]::OpenBaseKey($HiveEnum, $view)
            if ($baseKey) {
                $key = $baseKey.OpenSubKey($Subkey, $false)
                if ($key) {
                    $val = $key.GetValue($Item, $null)
                    $key.Close()
                    $baseKey.Close()
                    if ($null -ne $val) { return $true, $val }
                } else {
                    $baseKey.Close()
                }
            }
        } catch {}
    }
    return $false, $null
}

# ==============================================================================
# SECTION 6: VALUE MATCHING & HUMAN-READABLE FORMATTING HELPERS
# ==============================================================================
function ConvertTo-NormalizedRegistryPathList {
    param([object]$Value)

    $items = [System.Collections.Generic.List[string]]::new()
    if ($null -eq $Value) { return [string[]]@() }

    if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
        foreach ($v in $Value) {
            if ($null -ne $v) { $items.Add([string]$v) }
        }
    } else {
        $text = [string]$Value
        if ($text -match '&&') {
            $parts = [regex]::Split($text, '\s*&&\s*')
            foreach ($p in $parts) { $items.Add($p) }
        } elseif ($text -match '[\r\n]') {
            $parts = $text -split '[\r\n]+'
            foreach ($p in $parts) { $items.Add($p) }
        } elseif ($text.Contains(',')) {
            $parts = $text -split ','
            foreach ($p in $parts) { $items.Add($p) }
        } elseif ($text.Trim()) {
            $items.Add($text)
        }
    }

    $clean = [System.Collections.Generic.List[string]]::new()
    foreach ($item in $items) {
        $s = $item.Trim().Trim('"').Trim("'").Replace('/', '\')
        while ($s.Contains('\\')) { $s = $s.Replace('\\', '\') }
        $s = $s.TrimEnd('\').ToLowerInvariant()
        if ($s -and -not $clean.Contains($s)) {
            $clean.Add($s)
        }
    }
    $clean.Sort()
    return $clean.ToArray()
}

function Test-RegistryPathListMatch {
    param([object]$Actual, [string]$Expected)

    $actualList = [string[]](ConvertTo-NormalizedRegistryPathList -Value $Actual)
    $expectedList = [string[]](ConvertTo-NormalizedRegistryPathList -Value $Expected)

    if ($actualList.Length -ne $expectedList.Length) {
        return $false
    }
    for ($i = 0; $i -lt $expectedList.Length; $i++) {
        if ($actualList[$i] -ne $expectedList[$i]) {
            return $false
        }
    }
    return $true
}

function Test-SingleValueMatch {
    param([object]$Actual, [string]$Expected, [string]$VType, [string]$CType)

    if ($null -eq $Actual) { return $false }
    if ($VType -eq "POLICY_MULTI_TEXT" -or ($Expected -match '&&' -and $CType -notin @("CHECK_REGEX", "CHECK_NOT_REGEX"))) {
        return (Test-RegistryPathListMatch -Actual $Actual -Expected $Expected)
    }

    $exp = $Expected.Trim().Trim('"').Trim("'")
    $actStr = if ($Actual -is [System.Collections.IEnumerable] -and $Actual -isnot [string]) {
        ($Actual | ForEach-Object { "$_" }) -join ", "
    } else {
        "$Actual"
    }
    $actStr = $actStr.Trim()

    if ($CType -eq "CHECK_REGEX") {
        return ($actStr -match $exp)
    }
    if ($CType -eq "CHECK_NOT_REGEX") {
        return ($actStr -notmatch $exp)
    }
    if ($CType -eq "CHECK_NOT_EQUAL") {
        return ($actStr.ToLower() -ne $exp.ToLower())
    }

    if ($Expected.Trim() -match '^\[\s*(\d+)\s*\.\.\s*(MAX|\d+)\s*\]$') {
        $minV = [long]$Matches[1]
        $maxV = if ($Matches[2] -eq 'MAX') { [long]::MaxValue } else { [long]$Matches[2] }
        try { $actNum = [long]$actStr; return ($actNum -ge $minV -and $actNum -le $maxV) } catch { return $false }
    }
    if ($Expected.Trim() -match '^\[\s*MIN\s*\.\.\s*(\d+)\s*\]$') {
        $maxV2 = [long]$Matches[1]
        try { $actNum2 = [long]$actStr; return ($actNum2 -le $maxV2) } catch { return $false }
    }

    if ($VType -eq "POLICY_DWORD" -or ($actStr -match '^-?\d+$' -and $exp -match '^-?\d+$')) {
        try { return ([long]$actStr -eq [long]$exp) } catch {}
    }

    return ($actStr.ToLower() -eq $exp.ToLower())
}

function Test-ValueMatch {
    param([object]$Actual, [string]$Expected, [string]$VType, [string]$CType)

    if ($null -eq $Actual) { return $false }
    if ($Expected -match '\|\|') {
        $clauses = $Expected -split '\|\|'
        foreach ($clause in $clauses) {
            $cTrim = $clause.Trim()
            if ($cTrim -and (Test-SingleValueMatch -Actual $Actual -Expected $cTrim -VType $VType -CType $CType)) {
                return $true
            }
        }
        return $false
    }

    return Test-SingleValueMatch -Actual $Actual -Expected $Expected -VType $VType -CType $CType
}

function Format-HumanReadableExpected {
    param([string]$RawVal, [string]$AuditType, [string]$RuleId)

    if (-not $RawVal) { return "" }
    $v = $RawVal.Trim()

    switch ($v) {
        "2147483640"             { return "AES128, AES256, Future encryption types (0x7FFFFFF8)" }
        "537395200"              { return "Require NTLMv2 & 128-bit encryption (0x20080000)" }
        "O:BAG:BAD:(A;;RC;;;BA)" { return "Administrators: Remote Access: Allow" }
        '""'                     { return "None (blank)" }
        "''"                     { return "None (blank)" }
    }

    if ($RuleId -eq "2.3.1.3" -or $v -match 'Admin\(istrator\)\?') {
        return "Any custom name other than 'Administrator'"
    }
    if ($RuleId -eq "2.3.1.4" -and $v -eq "Guest") {
        return "Any custom name other than 'Guest'"
    }
    if ($RuleId -eq "2.2.13") {
        return "Administrators (and NT VIRTUAL MACHINE\Virtual Machines if Hyper-V installed)"
    }

    # Range syntax
    if ($v -match '^\[\s*(\d+)\s*\.\.\s*MAX\s*\]$') {
        $n = [long]$Matches[1]
        $nStr = "{0:N0}" -f $n
        return "$nStr or greater"
    }
    if ($v -match '^\[\s*MIN\s*\.\.\s*(\d+)\s*\]$') {
        $n = [long]$Matches[1]
        $nStr = "{0:N0}" -f $n
        return "$nStr or fewer"
    }
    if ($v -match '^\[\s*(\d+)\s*\.\.\s*(\d+)\s*\]$') {
        $n1 = [long]$Matches[1]
        $n2 = [long]$Matches[2]
        return "$n1 to $n2"
    }

    # AND operator
    if ($v -match '&&') {
        $parts = $v -split '&&' | ForEach-Object { $_.Trim().Trim('"').Trim("'").Trim('(').Trim(')') } | Where-Object { $_ }
        return ($parts -join ", ")
    }

    # OR operator
    if ($v -match '\|\|') {
        $parts = $v -split '\|\|' | ForEach-Object { $_.Trim().Trim('"').Trim("'").Trim('(').Trim(')') } | Where-Object { $_ }
        if ($parts.Count -gt 1) {
            $last = $parts[-1]
            $init = $parts[0..($parts.Count - 2)] -join ", "
            return "$init or $last"
        }
    }

    return $v.Trim('"').Trim("'")
}

function Format-HumanReadableActual {
    param([object]$RawAct, [string]$AuditType, [string]$RuleId)

    if ($null -eq $RawAct) { return "Not Configured / Key or Value Not Found" }

    $actStr = if ($RawAct -is [System.Collections.IEnumerable] -and $RawAct -isnot [string]) {
        $flat = @($RawAct | ForEach-Object {
            if ($_ -is [System.Collections.IEnumerable] -and $_ -isnot [string]) {
                $_ | ForEach-Object { "$_" }
            } else {
                "$_"
            }
        } | Where-Object { $_ -and $_ -ne "System.Object[]" })
        $flat -join ", "
    } else {
        "$RawAct"
    }
    $actStr = $actStr.Trim()
    if ($actStr -eq "System.Object[]") { $actStr = "Not Configured" }

    if ($RuleId -eq "2.3.1.3") {
        if ($actStr.ToLower() -eq "administrator") {
            return "Administrator (Default / Not Renamed)"
        } elseif ($actStr -and $actStr -notmatch 'Not Found') {
            return "Renamed to: $actStr"
        }
    }
    if ($RuleId -eq "2.3.1.4") {
        if ($actStr.ToLower() -eq "guest") {
            return "Guest (Default / Not Renamed)"
        } elseif ($actStr -and $actStr -notmatch 'Not Found') {
            return "Renamed to: $actStr"
        }
    }

    if ($actStr -eq "2147483640") {
        return "AES128, AES256, Future encryption types (0x7FFFFFF8)"
    }
    if ($actStr -eq "537395200") {
        return "Require NTLMv2 & 128-bit encryption (0x20080000)"
    }

    if ($AuditType -eq "REGISTRY_SETTING" -and $RuleId -match '^5\.') {
        switch ($actStr) {
            "4" { return "Disabled (4)" }
            "3" { return "Manual (3)" }
            "2" { return "Automatic (2)" }
        }
    }

    return $actStr
}

function Test-AuditpolMatch {
    param([string]$Actual, [string]$Expected)
    $act        = $Actual.ToLower()
    $hasSuccess = $act -match 'success'
    $hasFailure = $act -match 'failure'

    $clauses = $Expected -split '\|\|'
    foreach ($clause in $clauses) {
        $cl = $clause.Trim().Trim('"').ToLower()
        if ($cl -match 'success' -and $cl -match 'failure') { if ($hasSuccess -and $hasFailure) { return $true } }
        elseif ($cl -match 'success')                        { if ($hasSuccess) { return $true } }
        elseif ($cl -match 'failure')                        { if ($hasFailure) { return $true } }
        elseif ($cl -match 'no auditing')                    { if ($act -match 'no auditing' -or $act -eq '') { return $true } }
    }
    return $false
}

function Evaluate-AccountPolicy {
    param([string]$PolName, [string]$Expected, [string]$VType)
    $p = $PolName.ToUpper()

    $secMap = @{
        "ENFORCE_PASSWORD_HISTORY"  = "passwordhistorysize"
        "MAXIMUM_PASSWORD_AGE"      = "maximumpasswordage"
        "MINIMUM_PASSWORD_AGE"      = "minimumpasswordage"
        "MINIMUM_PASSWORD_LENGTH"   = "minimumpasswordlength"
        "COMPLEXITY_REQUIREMENTS"   = "passwordcomplexity"
        "REVERSIBLE_ENCRYPTION"     = "cleartextpassword"
        "LOCKOUT_DURATION"          = "lockoutduration"
        "LOCKOUT_THRESHOLD"         = "lockoutbadcount"
        "LOCKOUT_RESET"             = "resetlockoutcount"
        "FORCE_LOGOFF"              = "forcelogoffwhenhourexpire"
        "LOCKOUT_ADMINS"            = "allowadministratorlockout"
    }
    $netMap = @{
        "ENFORCE_PASSWORD_HISTORY"  = "length of password history maintained"
        "MAXIMUM_PASSWORD_AGE"      = "maximum password age (days)"
        "MINIMUM_PASSWORD_AGE"      = "minimum password age (days)"
        "MINIMUM_PASSWORD_LENGTH"   = "minimum password length"
        "LOCKOUT_DURATION"          = "lockout duration (minutes)"
        "LOCKOUT_THRESHOLD"         = "lockout threshold"
        "LOCKOUT_RESET"             = "lockout observation window (minutes)"
        "FORCE_LOGOFF"              = "force user logoff how long after time expires?"
    }

    # 1. Check in secedit
    $secKey = $secMap[$p]
    if ($secKey -and $Script:SecpolData.ContainsKey($secKey)) {
        $rawV = $Script:SecpolData[$secKey]
        if ($p -in @("COMPLEXITY_REQUIREMENTS","FORCE_LOGOFF","LOCKOUT_ADMINS","REVERSIBLE_ENCRYPTION")) {
            $act = if ($rawV -eq '1') { "Enabled" } else { "Disabled" }
            $st  = if ($act.ToLower() -eq $Expected.Trim('"').ToLower()) { "PASSED" } else { "FAILED" }
            return [PSCustomObject]@{ Actual = $act; Status = $st }
        } else {
            try {
                $valInt = [long]$rawV
                $match  = Test-ValueMatch -Actual $valInt -Expected $Expected -VType $VType -CType "NONE"
                $st2    = if ($match) { "PASSED" } else { "FAILED" }
                return [PSCustomObject]@{ Actual = "$valInt"; Status = $st2 }
            } catch {}
        }
    }

    # 2. Check in net accounts
    $netKey = $netMap[$p]
    if ($netKey -and $Script:NetAccountsData.ContainsKey($netKey)) {
        $rawV2 = $Script:NetAccountsData[$netKey]
        $valNum = 0
        if ($rawV2 -match 'unlimited|none|never') { $valNum = 0 }
        elseif ($rawV2 -match '(\d+)') { $valNum = [long]$Matches[1] }
        $match2 = Test-ValueMatch -Actual $valNum -Expected $Expected -VType $VType -CType "NONE"
        $st3    = if ($match2) { "PASSED" } else { "FAILED" }
        return [PSCustomObject]@{ Actual = "$rawV2 ($valNum)"; Status = $st3 }
    }

    return [PSCustomObject]@{ Actual = "Not Configured / Requires Admin Access"; Status = "MANUAL_REVIEW" }
}

function Resolve-SIDs {
    param([string]$SidsRaw)
    if (-not $SidsRaw) { return @() }
    $tokens = ($SidsRaw -split ',') | ForEach-Object { $_.Trim().TrimStart('*') } | Where-Object { $_ }
    $names = [System.Collections.Generic.List[string]]::new()
    foreach ($t in $tokens) {
        $n = ""
        if ($SID_NAME_MAP.ContainsKey($t)) { $n = $SID_NAME_MAP[$t] }
        elseif ($Script:LocalUsers.ContainsKey($t)) { $n = $Script:LocalUsers[$t].Name }
        else { $n = $t }
        if ($n -and -not $names.Contains($n)) { $names.Add($n) }
    }
    return $names.ToArray()
}

function Test-UserRightsClause {
    param([string[]]$ActualNames, [string]$Clause)
    if (-not $Clause) { return $false }
    $safeActual = @()
    if ($ActualNames) { $safeActual = @($ActualNames) }
    if ($safeActual.Count -eq 0) { return $false }

    $parts   = ($Clause -split '&&') | ForEach-Object { $_.Trim().Trim('"').Trim("'") } | Where-Object { $_ }
    $actLow  = @($safeActual | ForEach-Object { if ($_) { $_.ToString().ToLower() } })
    foreach ($p in $parts) {
        if (-not $p) { continue }
        $pLow  = $p.ToLower()
        $found = $actLow | Where-Object { $_ -eq $pLow -or $_ -like "*$pLow*" }
        if (-not $found) { return $false }
    }
    return $true
}

function Test-UserRightsMatch {
    param([string[]]$ActualNames, [string]$Expected)
    $exp = if ($Expected) { $Expected.Trim() } else { "" }
    $safeActual = @()
    if ($ActualNames) { $safeActual = @($ActualNames) }

    if (-not $exp -or $exp -in @('""', "''")) { return ($safeActual.Count -eq 0) }
    if ($safeActual.Count -eq 0) { return $false }

    if ($exp -match '\|\|') {
        $clauses = ($exp -split '\|\|') | ForEach-Object { $_.Trim().Trim('()') }
        foreach ($cl in $clauses) {
            if (Test-UserRightsClause -ActualNames $safeActual -Clause $cl) { return $true }
        }
        return $false
    }
    return Test-UserRightsClause -ActualNames $safeActual -Clause $exp
}

# ==============================================================================
# SECTION 7: CHECK EVALUATOR
# ==============================================================================
function Get-Val { param($Hashtable, [string]$Key, $Default = "") 
    $v = $Hashtable[$Key]; if ($null -ne $v -and $v -ne '') { return $v } else { return $Default }
}

function Evaluate-Item {
    param([hashtable]$Item)

    $itype     = Get-Val $Item 'type'          'UNKNOWN'
    $desc      = Get-Val $Item 'description'   'No description'
    $vtype     = Get-Val $Item 'value_type'    ''
    $vdata     = (Get-Val $Item 'value_data'   '').Trim()
    $ctype     = Get-Val $Item 'check_type'    'NONE'
    $regKey    = Get-Val $Item 'reg_key'       ''
    $regItem   = Get-Val $Item 'reg_item'      ''
    $regOption = Get-Val $Item 'reg_option'    'CAN_NOT_BE_NULL'
    $solution  = Get-Val $Item 'solution'      ''
    $info      = Get-Val $Item 'info'          ''
    $reference = Get-Val $Item 'reference'     ''

    $ruleId        = (Get-Val $Item 'benchmark_rule_id'     '').Trim()
    $benchmarkDesc = (Get-Val $Item 'benchmark_description' '').Trim()

    if (-not $ruleId) {
        $ruleId = Get-SpecificRuleId -Description $desc
        if (-not $ruleId) { $ruleId = "GENERAL" }
    }

    $actualValue   = "Not Found / Not Configured"
    $status        = "FAILED"

    $targetSetting = $regKey
    if (-not $targetSetting) {
        if ($Item['right_type'])                   { $targetSetting = $Item['right_type'] }
        elseif ($Item['audit_policy_subcategory']) { $targetSetting = $Item['audit_policy_subcategory'] }
        elseif ($Item['password_policy'])          { $targetSetting = $Item['password_policy'] }
        elseif ($Item['lockout_policy'])           { $targetSetting = $Item['lockout_policy'] }
        else                                       { $targetSetting = $itype }
    }

    $targetItem = $regItem
    if (-not $targetItem) {
        if ($Item['key_item'])         { $targetItem = $Item['key_item'] }
        elseif ($Item['account_type']) { $targetItem = $Item['account_type'] }
        else                           { $targetItem = "" }
    }

    try {
        switch ($itype) {

            { $_ -in @("REGISTRY_SETTING","BANNER_CHECK") } {
                $ok, $val = Read-Registry -RegKey $regKey -RegItem $regItem
                $rawVal = $val
                if ($val -is [System.Collections.IEnumerable] -and $val -isnot [string]) {
                    $val = ($val | Where-Object { $_ }) -join ", "
                }
                if ($regOption -eq "MUST_NOT_EXIST") {
                    if (-not $ok) { $actualValue = "Key/Value does not exist"; $status = "PASSED" }
                    else          { $actualValue = "$val"; $status = "FAILED" }
                } elseif (-not $ok) {
                    if ($regOption -eq "CAN_BE_NULL" -and $vdata -in @("","0",'""')) {
                        $actualValue = "Not Configured (Allowed Null)"; $status = "PASSED"
                    } else {
                        $actualValue = "Not Configured / Key or Value Not Found"; $status = "FAILED"
                    }
                } else {
                    $actualValue = "$val"
                    $matchVal = if ($null -ne $rawVal) { $rawVal } else { $val }
                    $match = Test-ValueMatch -Actual $matchVal -Expected $vdata -VType $vtype -CType $ctype
                    $status = if ($match) { "PASSED" } else { "FAILED" }
                }
            }

            "REG_CHECK" {
                $rk = $regKey
                if ($vdata -match '^HK') { $rk = $vdata }
                $ri = $regItem
                if ($Item['key_item']) { $ri = $Item['key_item'] }
                $targetSetting = $rk
                $targetItem    = $ri
                $ok, $val = Read-Registry -RegKey $rk -RegItem $ri
                if ($regOption -eq "MUST_NOT_EXIST") {
                    if (-not $ok) { $actualValue = "Value does not exist"; $status = "PASSED" }
                    else          { $actualValue = "$val"; $status = "FAILED" }
                } else {
                    $actualValue = if ($ok) { "$val" } else { "Not Configured" }
                    $status      = if ($ok) { "PASSED" } else { "FAILED" }
                }
            }

            "AUDIT_POLICY_SUBCATEGORY" {
                $subcatRaw = ""
                if ($Item['audit_policy_subcategory']) { $subcatRaw = $Item['audit_policy_subcategory'].Trim() }
                $targetSetting = "Audit Subcategory: $subcatRaw"
                if (-not $Script:AuditpolData.Count) {
                    $actualValue = "Audit policy requires Administrator privileges to query"
                    $status = "MANUAL_REVIEW"
                } else {
                    $subcatKey   = $subcatRaw.ToLower()
                    $currSetting = $Script:AuditpolData[$subcatKey]
                    if (-not $currSetting) {
                        $matchKey = $Script:AuditpolData.Keys | Where-Object { $_ -like "*$subcatKey*" -or $subcatKey -like "*$_*" } | Select-Object -First 1
                        if ($matchKey) { $currSetting = $Script:AuditpolData[$matchKey] }
                    }
                    if ($currSetting) {
                        $actualValue = $currSetting
                        $status = if (Test-AuditpolMatch -Actual $currSetting -Expected $vdata) { "PASSED" } else { "FAILED" }
                    } else {
                        $actualValue = "Subcategory Not Found"; $status = "FAILED"
                    }
                }
            }

            { $_ -in @("PASSWORD_POLICY","LOCKOUT_POLICY") } {
                $polName = if ($Item['password_policy']) { $Item['password_policy'] } elseif ($Item['lockout_policy']) { $Item['lockout_policy'] } else { "" }
                $targetSetting = "Policy: $polName"
                $evalRes = Evaluate-AccountPolicy -PolName $polName -Expected $vdata -VType $vtype
                $actualValue = $evalRes.Actual
                $status      = $evalRes.Status
            }

            "USER_RIGHTS_POLICY" {
                $right = if ($Item['right_type']) { $Item['right_type'] } else { "" }
                $targetSetting = "User Right: $right"
                if (-not $IsAdmin -and -not $Script:UserRightsData.Count) {
                    $actualValue = "User rights require Administrator privileges (secedit export)"
                    $status = "MANUAL_REVIEW"
                } else {
                    $assignedStr   = if ($Script:UserRightsData.ContainsKey($right)) { $Script:UserRightsData[$right] } else { "" }
                    $rawNames      = @(Resolve-SIDs -SidsRaw $assignedStr)
                    $resolvedNames = @($rawNames | ForEach-Object {
                        if ($_ -is [System.Collections.IEnumerable] -and $_ -isnot [string]) {
                            $_ | ForEach-Object { "$_" }
                        } else {
                            "$_"
                        }
                    } | Where-Object { $_ -and $_ -ne "System.Object[]" })

                    $actualValue   = if ($resolvedNames -and $resolvedNames.Count -gt 0) { $resolvedNames -join ", " } else { "No One" }
                    $status        = if (Test-UserRightsMatch -ActualNames $resolvedNames -Expected $vdata) { "PASSED" } else { "FAILED" }
                }
            }

            "CHECK_ACCOUNT" {
                $acctType = if ($Item['account_type']) { $Item['account_type'] } else { "" }
                $targetSetting = "Account: $acctType"
                if ($acctType -eq "GUEST_ACCOUNT") {
                    $guest = $Script:LocalUsers.Values | Where-Object { $_.SID -match '-501$' } | Select-Object -First 1
                    if ($guest) {
                        $actualName = $guest.Name
                        $isDis      = $guest.Disabled
                        if ($desc -match 'Rename') {
                            $actualValue = $actualName
                            $status = if ($actualName.ToLower() -ne 'guest') { "PASSED" } else { "FAILED" }
                        } else {
                            $actualValue = if ($isDis) { "Disabled" } else { "Enabled" }
                            $status = if ($isDis) { "PASSED" } else { "FAILED" }
                        }
                    } else { $actualValue = "Guest account not found"; $status = "PASSED" }
                } elseif ($acctType -eq "ADMINISTRATOR_ACCOUNT") {
                    $admin = $Script:LocalUsers.Values | Where-Object { $_.SID -match '-500$' } | Select-Object -First 1
                    if ($admin) {
                        $actualName = $admin.Name; $actualValue = $actualName
                        if ($ctype -eq "CHECK_NOT_REGEX") {
                            $pat = $vdata.Trim('"')
                            $status = if ($actualName -match $pat) { "FAILED" } else { "PASSED" }
                        } else {
                            $status = if ($actualName.ToLower() -ne 'administrator') { "PASSED" } else { "FAILED" }
                        }
                    } else { $actualValue = "Administrator account not found"; $status = "FAILED" }
                } else {
                    $actualValue = "Account type check not supported: $acctType"
                    $status = "MANUAL_REVIEW"
                }
            }

            "ANONYMOUS_SID_SETTING" {
                $targetSetting = "Network access: Allow anonymous SID/Name translation"
                $ok, $val = Read-Registry -RegKey "HKLM\SYSTEM\CurrentControlSet\Control\Lsa" -RegItem "TurnOffAnonymousBlock"
                $secVal = if ($Script:SecpolData.ContainsKey('lsaanonymousnamelookup')) { $Script:SecpolData['lsaanonymousnamelookup'] } else { "0" }
                if ($secVal -eq "0" -or ($ok -and $val -eq 1)) {
                    $actualValue = "Disabled (Protected)"; $status = "PASSED"
                } else {
                    $actualValue = "Enabled (Vulnerable)"; $status = "FAILED"
                }
            }

            default {
                $actualValue = "Check type not supported directly: $itype"
                $status = "MANUAL_REVIEW"
            }
        }
    } catch {
        $actualValue = "Error evaluating check: $($_.Exception.Message)"
        $status = "ERROR"
    }

    $finalDesc = if ($benchmarkDesc) { $benchmarkDesc } else { $desc }
    return [PSCustomObject]@{
        Rule_ID               = $ruleId
        Description           = $finalDesc
        Benchmark_Description = $benchmarkDesc
        Audit_Type            = $itype
        Target_Setting        = $targetSetting
        Target_Item           = $targetItem
        Expected_Value        = $vdata
        Actual_Value          = $actualValue
        Status                = $status
        Solution              = $solution
        Info                  = $info
        Reference             = $reference
    }
}

# ==============================================================================
# SECTION 8: RESULT COLLAPSER (1 ROW PER SPECIFIC CIS RECOMMENDATION)
# ==============================================================================
function Collapse-Results {
    param([object[]]$Results)

    $grouped    = [ordered]@{}
    $unresolved = @()

    foreach ($r in $Results) {
        $rid = "$($r.Rule_ID)".Trim()
        if (-not $rid -or $rid -eq 'GENERAL') { $unresolved += $r; continue }
        if (-not $grouped.Contains($rid)) { $grouped[$rid] = @() }
        $grouped[$rid] += $r
    }

    function Collapse-Status([object[]]$Rows) {
        $statuses = $Rows | ForEach-Object { "$($_.Status)".ToUpper() }
        if ('FAILED' -in $statuses)        { return "FAILED" }
        if ('ERROR' -in $statuses)         { return "ERROR" }
        if ('MANUAL_REVIEW' -in $statuses) { return "MANUAL_REVIEW" }
        if ('PASSED' -in $statuses)        { return "PASSED" }
        return "MANUAL_REVIEW"
    }

    function Join-Unique([object[]]$Rows, [string]$Key) {
        $vals = @()
        foreach ($row in $Rows) {
            $raw = $row.$Key
            $v = if ($raw -is [System.Collections.IEnumerable] -and $raw -isnot [string]) {
                $flat = @($raw | ForEach-Object {
                    if ($_ -is [System.Collections.IEnumerable] -and $_ -isnot [string]) {
                        $_ | ForEach-Object { "$_" }
                    } else {
                        "$_"
                    }
                } | Where-Object { $_ -and $_ -ne "System.Object[]" })
                $flat -join ", "
            } else {
                "$raw"
            }
            $v = $v.Trim()
            if ($v -and $v -notin $vals -and $v -ne "System.Object[]") { $vals += $v }
        }
        return $vals -join " | "
    }

    $final = @()
    $seen  = [System.Collections.Generic.HashSet[string]]::new()

    foreach ($r in $Results) {
        $rid = "$($r.Rule_ID)".Trim()
        if (-not $rid -or $rid -eq 'GENERAL' -or $seen.Contains($rid)) { continue }
        [void]$seen.Add($rid)
        $rows = $grouped[$rid]

        $descriptions = @()
        foreach ($row in $rows) {
            $bd = "$($row.Benchmark_Description)".Trim()
            $d  = if ($bd) { $bd } else { "$($row.Description)".Trim() }
            if ($d -and $d -notin $descriptions) { $descriptions += $d }
        }
        $benchDesc = if ($descriptions.Count -gt 0) { $descriptions[0] } else { "" }

        $finalDesc = if ($benchDesc) { $benchDesc } else { "$($rows[0].Description)" }

        $expVal = Join-Unique -Rows $rows -Key "Expected_Value"
        $actVal = Join-Unique -Rows $rows -Key "Actual_Value"
        $solVal = Join-Unique -Rows $rows -Key "Solution"

        $fmtExp   = Format-HumanReadableExpected -RawVal $expVal -AuditType $rows[0].Audit_Type -RuleId $rid
        $fmtAct   = Format-HumanReadableActual -RawAct $actVal -AuditType $rows[0].Audit_Type -RuleId $rid
        $cleanSol = $solVal.Trim().Trim('"').Trim("'").Trim()

        $base = [PSCustomObject]@{
            Rule_ID               = $rid
            Description           = $finalDesc
            Benchmark_Description = $benchDesc
            Audit_Type            = $rows[0].Audit_Type
            Target_Setting        = $rows[0].Target_Setting
            Target_Item           = Join-Unique -Rows $rows -Key "Target_Item"
            Expected_Value        = $fmtExp
            Actual_Value          = $fmtAct
            Status                = Collapse-Status -Rows $rows
            Solution              = $cleanSol
            Info                  = Join-Unique -Rows $rows -Key "Info"
            Reference             = Join-Unique -Rows $rows -Key "Reference"
        }
        $final += $base
    }

    $unresSeen = [System.Collections.Generic.HashSet[string]]::new()
    foreach ($r in $unresolved) {
        $uk = "$($r.Description)|$($r.Target_Setting)|$($r.Target_Item)"
        if ($unresSeen.Contains($uk)) { continue }
        [void]$unresSeen.Add($uk)
        $r.Expected_Value = Format-HumanReadableExpected -RawVal $r.Expected_Value -AuditType $r.Audit_Type -RuleId $r.Rule_ID
        $r.Actual_Value   = Format-HumanReadableActual -RawAct $r.Actual_Value -AuditType $r.Audit_Type -RuleId $r.Rule_ID
        if ($r.Solution) { $r.Solution = $r.Solution.Trim().Trim('"').Trim("'").Trim() }
        $final += $r
    }

    return $final
}

# ==============================================================================
# SECTION 9: REPORT EXPORTER (CSV + EXACT OPENXML EXCEL .XLSX)
# ==============================================================================
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem

function Escape-Xml([string]$text) {
    if (-not $text) { return "" }
    $clean = [System.Text.RegularExpressions.Regex]::Replace($text, "[\x00-\x08\x0B\x0C\x0E-\x1F\uFFFE\uFFFF]", "")
    return $clean.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace('"', "&quot;").Replace("'", "&apos;")
}

function Export-Reports {
    param(
        [object[]]$Results,
        [string]$OutputPrefix,
        [hashtable]$TargetInfo
    )

    $csvFile  = "$OutputPrefix.csv"
    $xlsxFile = "$OutputPrefix.xlsx"

    # 1. Export CSV
    $headers = @("Rule_ID","Description","Status","Audit_Type","Target_Setting","Target_Item","Expected_Value","Actual_Value","Solution","Reference")
    $Results | Select-Object $headers | Export-Csv -LiteralPath $csvFile -NoTypeInformation -Encoding UTF8
    Write-Host "[+] CSV Report Created   : $csvFile" -ForegroundColor Green

    # 2. Export Exact OpenXML Excel (.xlsx)
    try {
        if (Test-Path -LiteralPath $xlsxFile) { Remove-Item -LiteralPath $xlsxFile -Force -ErrorAction SilentlyContinue }

        $totalControls = $Results.Count
        $passedCount   = ($Results | Where-Object { $_.Status -eq "PASSED" }).Count
        $failedCount   = ($Results | Where-Object { $_.Status -eq "FAILED" }).Count
        $reviewCount   = ($Results | Where-Object { $_.Status -eq "MANUAL_REVIEW" }).Count
        $errorCount    = ($Results | Where-Object { $_.Status -eq "ERROR" }).Count
        $passRate      = if ($totalControls -gt 0) { [Math]::Round(($passedCount / $totalControls) * 100, 1) } else { 0 }

        $contentTypesXml = @'
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/><Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/></Types>
'@

        $rootRelsXml = @'
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml" Id="rId1"/><Relationship Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml" Id="rId2"/><Relationship Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml" Id="rId3"/></Relationships>
'@

        $appXml = @'
<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"><Application>Microsoft Excel</Application></Properties>
'@

        $nowUtc = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
        $coreXml = @"
<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:dcmitype="http://purl.org/dc/dcmitype/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:creator>CIS Auditor</dc:creator><cp:lastModifiedBy>CIS Auditor</cp:lastModifiedBy><dcterms:created xsi:type="dcterms:W3CDTF">$nowUtc</dcterms:created><dcterms:modified xsi:type="dcterms:W3CDTF">$nowUtc</dcterms:modified></cp:coreProperties>
"@

        $maxRow = $Results.Count + 1
        $workbookXml = @"
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><workbookPr/><bookViews><workbookView visibility="visible" minimized="0" showHorizontalScroll="1" showVerticalScroll="1" showSheetTabs="1" tabRatio="600" firstSheet="0" activeTab="0"/></bookViews><sheets><sheet xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" name="Executive Summary" sheetId="1" state="visible" r:id="rId1"/><sheet xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" name="Detailed Audit Results" sheetId="2" state="visible" r:id="rId2"/></sheets><definedNames><definedName name="_xlnm._FilterDatabase" localSheetId="1" hidden="1">'Detailed Audit Results'!`$A`$1:`$J`$$maxRow</definedName></definedNames><calcPr calcId="124519" fullCalcOnLoad="1"/></workbook>
"@

        $workbookRelsXml = @'
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml" Id="rId1"/><Relationship Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml" Id="rId2"/><Relationship Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml" Id="rId3"/></Relationships>
'@

        # Sheet 1: Executive Summary XML
        $genDate       = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
        $hostName      = Escape-Xml $TargetInfo.Hostname
        $osPlatform    = Escape-Xml $TargetInfo.OSPlatform
        $buildNumber   = Escape-Xml $TargetInfo.BuildNumber
        $adminMode     = if ($TargetInfo.Admin) { "Administrator (Full Inspection)" } else { "Standard User (Partial Elevation Recommended)" }
        $csvReportPath = Escape-Xml (Resolve-Path $csvFile).Path
        $auditFileName = Escape-Xml $TargetInfo.AuditFileName

        $catCounts = [ordered]@{}
        foreach ($r in $Results) {
            $t = "$($r.Audit_Type)"
            if (-not $catCounts.Contains($t)) { $catCounts[$t] = @{ Total = 0; Passed = 0 } }
            $catCounts[$t].Total++
            if ($r.Status -eq "PASSED") { $catCounts[$t].Passed++ }
        }

        $sbSheet1 = [System.Text.StringBuilder]::new()
        [void]$sbSheet1.Append(@'
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><outlinePr summaryBelow="1" summaryRight="1"/><pageSetUpPr/></sheetPr><sheetViews><sheetView showGridLines="1" workbookViewId="0"><selection activeCell="A1" sqref="A1"/></sheetView></sheetViews><sheetFormatPr baseColWidth="8" defaultRowHeight="15"/><cols><col width="24" customWidth="1" min="2" max="2"/><col width="24" customWidth="1" min="3" max="3"/><col width="24" customWidth="1" min="4" max="4"/><col width="24" customWidth="1" min="5" max="5"/><col width="24" customWidth="1" min="6" max="6"/></cols><sheetData>
'@)

        [void]$sbSheet1.Append('<row r="2"><c r="B2" s="1" t="inlineStr"><is><t>Windows 11 CIS Configuration Audit Report</t></is></c></row>')
        [void]$sbSheet1.Append("<row r=""3""><c r=""B3"" s=""2"" t=""inlineStr""><is><t>Generated: $genDate | Target: $hostName | Benchmark: CIS Windows 11 Enterprise v5.1.0 L1</t></is></c></row>")

        # KPI Scorecard (Row 5 = Labels, Row 6 = Values)
        [void]$sbSheet1.Append('<row r="5">')
        [void]$sbSheet1.Append('<c r="B5" s="3" t="inlineStr"><is><t>TOTAL CONTROLS</t></is></c>')
        [void]$sbSheet1.Append('<c r="C5" s="4" t="inlineStr"><is><t>CONTROLS PASSED</t></is></c>')
        [void]$sbSheet1.Append('<c r="D5" s="5" t="inlineStr"><is><t>CONTROLS FAILED</t></is></c>')
        [void]$sbSheet1.Append('<c r="E5" s="6" t="inlineStr"><is><t>MANUAL REVIEW</t></is></c>')
        [void]$sbSheet1.Append('<c r="F5" s="7" t="inlineStr"><is><t>COMPLIANCE SCORE</t></is></c>')
        [void]$sbSheet1.Append('</row>')

        [void]$sbSheet1.Append('<row r="6">')
        [void]$sbSheet1.Append("<c r=""B6"" s=""8"" t=""n""><v>$totalControls</v></c>")
        [void]$sbSheet1.Append("<c r=""C6"" s=""9"" t=""n""><v>$passedCount</v></c>")
        [void]$sbSheet1.Append("<c r=""D6"" s=""10"" t=""n""><v>$failedCount</v></c>")
        [void]$sbSheet1.Append("<c r=""E6"" s=""11"" t=""n""><v>$reviewCount</v></c>")
        [void]$sbSheet1.Append("<c r=""F6"" s=""12"" t=""inlineStr""><is><t>$passRate%</t></is></c>")
        [void]$sbSheet1.Append('</row>')

        # Section Headers (Row 9)
        [void]$sbSheet1.Append('<row r="9">')
        [void]$sbSheet1.Append('<c r="B9" s="13" t="inlineStr"><is><t>Target System Information</t></is></c>')
        [void]$sbSheet1.Append('<c r="C9" s="13"/>')
        [void]$sbSheet1.Append('<c r="E9" s="13" t="inlineStr"><is><t>Control Category Breakdown</t></is></c>')
        [void]$sbSheet1.Append('<c r="F9" s="13"/>')
        [void]$sbSheet1.Append('<c r="G9" s="13"/>')
        [void]$sbSheet1.Append('</row>')

        # Subheaders (Row 10)
        [void]$sbSheet1.Append('<row r="10">')
        [void]$sbSheet1.Append('<c r="B10" s="14" t="inlineStr"><is><t>Computer Name</t></is></c>')
        [void]$sbSheet1.Append("<c r=""C10"" s=""15"" t=""inlineStr""><is><t>$hostName</t></is></c>")
        [void]$sbSheet1.Append('<c r="E10" s="16" t="inlineStr"><is><t>Audit Category</t></is></c>')
        [void]$sbSheet1.Append('<c r="F10" s="16" t="inlineStr"><is><t>Total</t></is></c>')
        [void]$sbSheet1.Append('<c r="G10" s="16" t="inlineStr"><is><t>Passed</t></is></c>')
        [void]$sbSheet1.Append('</row>')

        $sysList = @(
            @("Operating System", $osPlatform),
            @("Windows Build", $buildNumber),
            @("Scan Privilege Mode", $adminMode),
            @("Audit File Used", $auditFileName),
            @("CSV Report Path", $csvReportPath)
        )

        $catKeys = @($catCounts.Keys)
        $maxR = [Math]::Max(5, $catKeys.Count)

        for ($i = 0; $i -lt $maxR; $i++) {
            $rowNum = 11 + $i
            [void]$sbSheet1.Append("<row r=""$rowNum"">")
            if ($i -lt $sysList.Count) {
                $pName = Escape-Xml $sysList[$i][0]
                $pVal  = Escape-Xml $sysList[$i][1]
                [void]$sbSheet1.Append("<c r=""B$rowNum"" s=""14"" t=""inlineStr""><is><t>$pName</t></is></c>")
                [void]$sbSheet1.Append("<c r=""C$rowNum"" s=""15"" t=""inlineStr""><is><t>$pVal</t></is></c>")
            }
            if ($i -lt $catKeys.Count) {
                $catName = Escape-Xml $catKeys[$i]
                $cTot    = $catCounts[$catKeys[$i]].Total
                $cPas    = $catCounts[$catKeys[$i]].Passed
                $cPct    = if ($cTot -gt 0) { [Math]::Round(($cPas / $cTot) * 100) } else { 0 }
                [void]$sbSheet1.Append("<c r=""E$rowNum"" s=""15"" t=""inlineStr""><is><t>$catName</t></is></c>")
                [void]$sbSheet1.Append("<c r=""F$rowNum"" s=""15"" t=""n""><v>$cTot</v></c>")
                [void]$sbSheet1.Append("<c r=""G$rowNum"" s=""15"" t=""inlineStr""><is><t>$cPas ($cPct%)</t></is></c>")
            }
            [void]$sbSheet1.Append('</row>')
        }

        [void]$sbSheet1.Append(@'
</sheetData><mergeCells count="2"><mergeCell ref="B9:C9"/><mergeCell ref="E9:G9"/></mergeCells><pageMargins left="0.75" right="0.75" top="1" bottom="1" header="0.5" footer="0.5"/></worksheet>
'@)

        # Sheet 2: Detailed Audit Results XML
        $sbSheet2 = [System.Text.StringBuilder]::new()
        [void]$sbSheet2.Append(@"
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><outlinePr summaryBelow="1" summaryRight="1"/><pageSetUpPr/></sheetPr><sheetViews><sheetView showGridLines="1" workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/><selection pane="bottomLeft" activeCell="A1" sqref="A1"/></sheetView></sheetViews><sheetFormatPr baseColWidth="8" defaultRowHeight="15"/><cols><col width="15" customWidth="1" min="1" max="1"/><col width="45" customWidth="1" min="2" max="2"/><col width="16" customWidth="1" min="3" max="3"/><col width="25" customWidth="1" min="4" max="4"/><col width="45" customWidth="1" min="5" max="5"/><col width="30" customWidth="1" min="6" max="6"/><col width="25" customWidth="1" min="7" max="7"/><col width="35" customWidth="1" min="8" max="8"/><col width="55" customWidth="1" min="9" max="9"/><col width="35" customWidth="1" min="10" max="10"/></cols><sheetData><row r="1"><c r="A1" s="17" t="inlineStr"><is><t>Rule ID</t></is></c><c r="B1" s="17" t="inlineStr"><is><t>Description</t></is></c><c r="C1" s="17" t="inlineStr"><is><t>Status</t></is></c><c r="D1" s="17" t="inlineStr"><is><t>Audit Type</t></is></c><c r="E1" s="17" t="inlineStr"><is><t>Target Setting</t></is></c><c r="F1" s="17" t="inlineStr"><is><t>Target Item</t></is></c><c r="G1" s="17" t="inlineStr"><is><t>Expected Value</t></is></c><c r="H1" s="17" t="inlineStr"><is><t>Actual Value</t></is></c><c r="I1" s="17" t="inlineStr"><is><t>Solution</t></is></c><c r="J1" s="17" t="inlineStr"><is><t>Reference</t></is></c></row>
"@)

        $rowNum = 2
        foreach ($r in $Results) {
            $st = "$($r.Status)".ToUpper()
            $stStyle = switch ($st) {
                "PASSED"        { 19 }
                "FAILED"        { 20 }
                default         { 18 }
            }

            [void]$sbSheet2.Append("<row r=""$rowNum"">")
            
            $colLetters = @('A','B','C','D','E','F','G','H','I','J')
            $vals = @(
                $r.Rule_ID, $r.Description, $r.Status, $r.Audit_Type, $r.Target_Setting,
                $r.Target_Item, $r.Expected_Value, $r.Actual_Value, $r.Solution, $r.Reference
            )

            for ($c = 0; $c -lt 10; $c++) {
                $colLetter = $colLetters[$c]
                $cellRef   = "$colLetter$rowNum"
                $cStyle    = if ($c -eq 2) { $stStyle } else { 18 }
                $rawVal    = "$($vals[$c])"
                if ($rawVal) {
                    $esc = Escape-Xml $rawVal
                    [void]$sbSheet2.Append("<c r=""$cellRef"" s=""$cStyle"" t=""inlineStr""><is><t xml:space=""preserve"">$esc</t></is></c>")
                } else {
                    [void]$sbSheet2.Append("<c r=""$cellRef"" s=""$cStyle"" t=""inlineStr""/>")
                }
            }

            [void]$sbSheet2.Append('</row>')
            $rowNum++
        }

        $lastRow = $rowNum - 1
        [void]$sbSheet2.Append(@"
</sheetData><autoFilter ref="A1:J$lastRow"/><pageMargins left="0.75" right="0.75" top="1" bottom="1" header="0.5" footer="0.5"/></worksheet>
"@)

        # Write to ZipArchive
        $zipFile = [System.IO.Compression.ZipFile]::Open($xlsxFile, [System.IO.Compression.ZipArchiveMode]::Create)
        
        function Add-ZipPart($zip, [string]$entryName, [string]$content) {
            $entry = $zip.CreateEntry($entryName, [System.IO.Compression.CompressionLevel]::Optimal)
            $stream = $entry.Open()
            $bytes = [System.Text.Encoding]::UTF8.GetBytes($content)
            $stream.Write($bytes, 0, $bytes.Length)
            $stream.Close()
        }

        Add-ZipPart $zipFile "[Content_Types].xml" $contentTypesXml
        Add-ZipPart $zipFile "_rels/.rels" $rootRelsXml
        Add-ZipPart $zipFile "docProps/app.xml" $appXml
        Add-ZipPart $zipFile "docProps/core.xml" $coreXml
        Add-ZipPart $zipFile "xl/workbook.xml" $workbookXml
        Add-ZipPart $zipFile "xl/_rels/workbook.xml.rels" $workbookRelsXml
        Add-ZipPart $zipFile "xl/styles.xml" $EmbeddedStylesXml
        Add-ZipPart $zipFile "xl/worksheets/sheet1.xml" $sbSheet1.ToString()
        Add-ZipPart $zipFile "xl/worksheets/sheet2.xml" $sbSheet2.ToString()

        $zipFile.Dispose()
        Write-Host "[+] Excel Report Created : $xlsxFile" -ForegroundColor Green
    } catch {
        Write-Host "[!] Note: Could not generate Excel report: $($_.Exception.Message)" -ForegroundColor Yellow
        $xlsxFile = $null
    }

    return $csvFile, $xlsxFile
}

# ==============================================================================
# SECTION 10: AUDIT EXECUTION ENGINE
# ==============================================================================
Write-Host "`n[*] Target Endpoint : $env:COMPUTERNAME" -ForegroundColor Cyan
Write-Host "[*] OS Platform     : $([System.Environment]::OSVersion.VersionString)" -ForegroundColor Cyan

$buildOk, $buildNum = Read-Registry -RegKey "HKLM\Software\Microsoft\Windows NT\CurrentVersion" -RegItem "CurrentBuild"
$displayBuild = if ($buildOk) { $buildNum } else { "Unknown" }
Write-Host "[*] Windows Build   : $displayBuild" -ForegroundColor Cyan
Write-Host "-------------------------------------------------------------------------------" -ForegroundColor DarkGray

# 1. Load benchmark audit definitions
$AuditText = Load-AuditContent -SpecifiedPath $AuditFile -BaseDir $ScriptDir

# 2. Parse benchmark variables and compliance rules
Write-Host "[*] Parsing CIS benchmark rules..." -ForegroundColor Cyan
$variables, $items = Parse-AuditFile -Text $AuditText
Write-Host "[+] Loaded $($variables.Count) benchmark variable(s)." -ForegroundColor Green
Write-Host "[+] Extracted $($items.Count) compliance check(s) to evaluate." -ForegroundColor Green
Write-Host "-------------------------------------------------------------------------------" -ForegroundColor DarkGray

# 3. Pre-fetch system security configurations
Write-Host "[*] Collecting system security policies and local account states..." -ForegroundColor Cyan
Fetch-NetAccounts
Fetch-LocalUsers
if ($IsAdmin) { Fetch-Secedit }
Fetch-Auditpol
Write-Host "[+] Environment inventory collection completed." -ForegroundColor Green
Write-Host "[*] Inspecting endpoint configuration against CIS benchmark..." -ForegroundColor Cyan

# 4. Evaluate all checks
$rawResults = @()
$idx = 0
foreach ($item in $items) {
    $idx++
    $res = Evaluate-Item -Item $item
    $rawResults += $res
    if ($idx % 50 -eq 0 -or $idx -eq $items.Count) {
        Write-Host "    -> Evaluated $idx / $($items.Count) checks..." -ForegroundColor DarkGray
    }
}

# 5. Collapse into 1 row per exact CIS Recommendation ID
$results = Collapse-Results -Results $rawResults

# 6. Statistics
$total   = $results.Count
$passed  = ($results | Where-Object { $_.Status -eq 'PASSED' }).Count
$failed  = ($results | Where-Object { $_.Status -eq 'FAILED' }).Count
$review  = ($results | Where-Object { $_.Status -eq 'MANUAL_REVIEW' }).Count
$errors  = ($results | Where-Object { $_.Status -eq 'ERROR' }).Count
$score   = if ($total -gt 0) { [Math]::Round(($passed / $total) * 100, 1) } else { 0 }

Write-Host ""
Write-Host "===============================================================================" -ForegroundColor Green
Write-Host "                       AUDIT EVALUATION COMPLETE                               " -ForegroundColor Green
Write-Host "===============================================================================" -ForegroundColor Green
Write-Host "  Total Controls Evaluated : $total" -ForegroundColor White
Write-Host "  Passed  (Compliant)      : $passed ($([Math]::Round(($passed/$total)*100,1))%)" -ForegroundColor Green
Write-Host "  Failed  (Non-Compliant)  : $failed ($([Math]::Round(($failed/$total)*100,1))%)" -ForegroundColor Red
Write-Host "  Manual Review / Warning  : $review ($([Math]::Round(($review/$total)*100,1))%)" -ForegroundColor Yellow
if ($errors -gt 0) { Write-Host "  Errors                   : $errors" -ForegroundColor DarkRed }
Write-Host "  Overall Compliance Rate  : $score%" -ForegroundColor Cyan
Write-Host "-------------------------------------------------------------------------------" -ForegroundColor DarkGray

# 7. Export Reports
$deviceName   = $env:COMPUTERNAME
$outputPrefix = Join-Path $ReportDir "${deviceName}_CIS_Windows_11_Enterprise_Audit_Results"

$targetInfo = @{
    Hostname      = $env:COMPUTERNAME
    OSPlatform    = [System.Environment]::OSVersion.VersionString
    BuildNumber   = "$displayBuild"
    Admin         = $IsAdmin
    AuditFileName = if ($AuditFile) { Split-Path -Leaf $AuditFile } else { "CIS_Microsoft_Windows_11_Enterprise_v5.1.0_L1.audit" }
}

Write-Host "[*] Exporting compliance reports..." -ForegroundColor Cyan
$csvPath, $xlsxPath = Export-Reports -Results $results -OutputPrefix $outputPrefix -TargetInfo $targetInfo

Write-Host ""
Write-Host "===============================================================================" -ForegroundColor Green
Write-Host "                       AUDIT COMPLETED SUCCESSFULLY!                           " -ForegroundColor Green
Write-Host "===============================================================================" -ForegroundColor Green
Write-Host "[*] Primary Excel Report : $xlsxPath" -ForegroundColor Cyan
Write-Host "[*] Companion CSV Report : $csvPath" -ForegroundColor Cyan

if ($OpenReport) {
    if ($xlsxPath -and (Test-Path -LiteralPath $xlsxPath)) {
        Write-Host "[*] Launching Excel report..." -ForegroundColor Yellow
        Start-Process $xlsxPath
    } elseif ($csvPath -and (Test-Path -LiteralPath $csvPath)) {
        Write-Host "[*] Launching CSV report..." -ForegroundColor Yellow
        Start-Process $csvPath
    }
}
